// Labels, buttons, panels, sliders, progress bars, canvases, toolbars and the lists that list boxes, combo boxes and
// tabbers have.

#include "gui_internal.hpp"
#include "memory.h"
#include <string>
#include <vector>
#include "runtime_internal.h"

extern "C" {
int32_t bb_gui_load_strip(const char* file, int32_t* size, int32_t* count, char* blank, int32_t max);
void    bb_copy_rect(int32_t sx, int32_t sy, int32_t w, int32_t h, int32_t dx, int32_t dy, int32_t source, int32_t destination);
}

namespace bb::gui {
	static int make(int kind, int style, int group, int x, int y, int w, int h, const char* what)
	{
		int     handle = create_gadget(kind, style, group, what);
		gadget* g      = gadget_of(handle);
		g->x           = x;
		g->y           = y;
		g->w           = w;
		g->h           = h;
		update_client(handle);
		g->visible = true;
		lock_layout(*g);
		return handle;
	}

	int make_gadget(int kind, int style, int group, int x, int y, int w, int h, const char* what)
	{
		return make(kind, style, group, x, y, w, h, what);
	}

	// How many icons the strip has, or the number that a list could use.
	static bool has_icons(gadget const& g)
	{
		return strip_of(g.strip) != nullptr;
	}

	// Lists have items that are counted from 0.
	static void need_list(gadget* g, const char* what)
	{
		if ((g->kind != K_LISTBOX) && (g->kind != K_COMBOBOX) && (g->kind != K_TABBER)) {
			(void)what;
			gui_error("Invalid Gadget type");
		}
	}

	static void check_index(gadget* g, int index, int extra)
	{
		if ((index < 0) || (index >= int(g->items.size) + extra)) {
			gui_error("Gadget item list index out of range");
		}
	}

	void select_item(int handle, int index, bool user)
	{
		gadget* g = gadget_of(handle);
		if (!g) {
			return;
		}
		g->selected = index;
		if (g->kind == K_LISTBOX) {
			clamp_scroll(*g);
		}
		if (user) {
			post_action(handle, index);
		}
		dirty();
	}

	// The most that a slider can have as its value: the whole range, but not what is seen.
	int slider_limit(gadget const& g)
	{
		int limit = (g.range_visible <= 0) ? g.range_total - 1 : g.range_total - g.range_visible;
		return limit < 0 ? 0 : limit;
	}

	bool slider_horizontal(gadget const& g)
	{
		return (g.style & 3) == 1;
	}
} // namespace bb::gui

