int32_t bb_create_label(const char* text, int32_t x, int32_t y, int32_t w, int32_t h, int32_t group, int32_t style)
{
	int handle = make(K_LABEL, style, group, x, y, w, h, "CreateLabel");
	set_string(gadget_of(handle)->text, text);
	return handle;
}

